const $=id=>document.getElementById(id), defaults={clean:10,short:10,medium:30,long:60,every:3,superEvery:6,sound:'chime',volume:65,auto:false};
let cfg={...defaults},lang='de',state={phase:'clean',round:0,remaining:600000,running:false,end:0},audio,wake,alarmLoop;
try{cfg={...defaults,...JSON.parse(localStorage.getItem('cad-settings')||'{}')};lang=localStorage.getItem('cad-lang')||'de';state=JSON.parse(localStorage.getItem('cad-state'))||{...state,remaining:cfg.clean*60000}}catch{}if(!['de','en'].includes(lang))lang='de';cfg.auto=false;
const words={de:{tag:'Ein bisschen sauberer. Ganz entspannt.',settings:'Einstellungen',eyebrow:'DEIN KLEINER PUTZRHYTHMUS',headline:'Kleine Schritte.<br>Sauberes Zuhause.',sub:'Ein Raum. Ein Anfang. Die Pause gehört dazu.',stop:'■  Stop / Abbruch',rhythm:'Dein Rhythmus',repeat:'Und dann wieder von vorn.',gentle:'Nicht alles auf einmal. Zehn Minuten sind ein guter Anfang.',local:'Deine Einstellungen bleiben auf diesem Gerät.',install:'App installieren ↗',notice:'Für zuverlässige Signaltöne die App geöffnet lassen. Bei gesperrtem Bildschirm kann der Browser Töne verzögern.',settingsHint:'Dein Tempo, deine Pausen. Änderungen starten einen neuen Ablauf.',sound:'Signalton',test:'♫ Ton anhören',volume:'Lautstärke',auto:'Nächste Phase automatisch starten',soundNote:'Die integrierten Töne werden synthetisch erzeugt. Keine externen Audioaufnahmen.',save:'Speichern & zurücksetzen',installHelp:'Im Browser-Menü „App installieren“ oder „Zum Startbildschirm hinzufügen“ wählen. Auf iPhone/iPad: Safari → Teilen → Zum Home-Bildschirm. Nach dem ersten Laden auch offline nutzbar.',close:'Schließen',clean:'Putzen',short:'Kurze Pause',medium:'Lange Pause',long:'Große Pause',every:'Lange Pause alle … Runden',superEvery:'Große Pause alle … Runden',start:'▶  Los geht’s',resume:'▶  Weiter',pause:'Ⅱ  Anhalten',hint:'Schnapp dir eine kleine Aufgabe.',breakHint:'Durchatmen. Diese Zeit gehört dir.',round:'Runde',next:'Danach',after:'Nach',rounds:'Runden',each:'Nach jeder Runde',minute:'Min.',chime:'Heller Chime',bell:'Glocke',soft:'Sanfte Töne',none:'Lautlos'},en:{tag:'A little cleaner. A little calmer.',settings:'Settings',eyebrow:'YOUR LITTLE CLEANING RHYTHM',headline:'Small steps.<br>A happier home.',sub:'One room. One start. Breaks are part of it.',stop:'■  Stop / reset',rhythm:'Your rhythm',repeat:'Then do it all again.',gentle:'Not all at once. Ten minutes is a lovely start.',local:'Your settings stay on this device.',install:'Install app ↗',notice:'Keep the app open for reliable sounds. When the screen is locked, your browser may delay alerts.',settingsHint:'Your pace, your breaks. Saving starts a fresh session.',sound:'Alert sound',test:'♫ Preview sound',volume:'Volume',auto:'Start the next phase automatically',soundNote:'Built-in sounds are synthesized. No external audio recordings.',save:'Save & reset',installHelp:'In your browser menu, choose “Install app” or “Add to home screen”. On iPhone/iPad: Safari → Share → Add to Home Screen. Works offline after the first load.',close:'Close',clean:'Cleaning',short:'Short break',medium:'Long break',long:'Extended break',every:'Long break every … rounds',superEvery:'Extended break every … rounds',start:'▶  Let’s start',resume:'▶  Continue',pause:'Ⅱ  Pause timer',hint:'Pick one small thing to tackle.',breakHint:'Take a breath. This time is yours.',round:'Round',next:'Up next',after:'After',rounds:'rounds',each:'After each round',minute:'min',chime:'Bright chime',bell:'Bell',soft:'Soft notes',none:'Silent'}};
const t=k=>words[lang][k];function persist(){try{localStorage.setItem('cad-state',JSON.stringify(state));localStorage.setItem('cad-settings',JSON.stringify(cfg));localStorage.setItem('cad-lang',lang)}catch{}}
function breakFor(n){return n%cfg.superEvery===0?'long':n%cfg.every===0?'medium':'short'}
function render(){document.documentElement.lang=lang;document.querySelectorAll('[data-t]').forEach(el=>el.innerHTML=t(el.dataset.t));$('lang').textContent=lang==='de'?'EN':'DE';$('steps').innerHTML=['clean','short','medium','long'].map((p,i)=>`<div class="step"><small>${i===0?t('clean'):i===1?t('each'):t('after')+' '+(i===2?cfg.every:cfg.superEvery)+' '+t('rounds')}</small><strong>${cfg[p]}</strong> <span>${t('minute')}</span></div>`).join('');document.querySelectorAll('#sound option').forEach(o=>o.textContent=t(o.value));update()}
function update(){const ms=state.running?Math.max(0,state.end-Date.now()):state.remaining;const seconds=Math.ceil(ms/1000);$('clock').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('phase').textContent='●  '+t(state.phase);$('round').textContent=t('round')+' '+(state.phase==='clean'?state.round+1:state.round);$('hint').textContent=t(state.phase==='clean'?'hint':'breakHint');$('start').textContent=t(state.running?'pause':state.remaining<cfg[state.phase]*60000?'resume':'start');const next=state.phase==='clean'?breakFor(state.round+1):'clean';if(state.awaiting){$('start').textContent=(lang==='de'?'✓ Alarm aus · ':'✓ Dismiss · ')+t(next)+(lang==='de'?' starten':' start');$('hint').textContent=lang==='de'?'Geschafft! Starte die nächste Phase, wenn du bereit bist.':'Done! Start the next phase when you are ready.';}$('next').textContent=t('next')+': '+cfg[next]+' '+t('minute')+' '+t(next);$('bar').style.width=Math.max(0,Math.min(100,100-ms/(cfg[state.phase]*60000)*100))+'%';document.body.classList.toggle('break',state.phase!=='clean');document.title=$('clock').textContent+' · '+t(state.phase)+' · Clean-a-Doro'}
async function unlock(){try{audio ||= new (window.AudioContext||window.webkitAudioContext)();await audio.resume()}catch{}}
function play(sound=cfg.sound,volume=cfg.volume){if(sound==='none'||!audio)return;const notes=sound==='bell'?[659,988]:sound==='soft'?[392,494,587]:[523.25,659.25,783.99];notes.forEach((hz,i)=>{const o=audio.createOscillator(),g=audio.createGain(),at=audio.currentTime+i*.22;o.type='sine';o.frequency.value=hz;g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(volume/100*.25,at+.02);g.gain.exponentialRampToValueAtTime(.001,at+1.5);o.connect(g);g.connect(audio.destination);o.start(at);o.stop(at+1.6)})}
async function wakeLock(){try{if(state.running&&navigator.wakeLock)wake=await navigator.wakeLock.request('screen');else if(wake){await wake.release();wake=null}}catch{}}
function silence(){clearInterval(alarmLoop);alarmLoop=null;if(audio){audio.close().catch(()=>{});audio=null}}
function alarm(){play();clearInterval(alarmLoop);alarmLoop=setInterval(()=>play(),3500)}
function tick(){if(state.running&&Date.now()>=state.end){state.remaining=0;state.running=false;state.awaiting=true;alarm();persist();wakeLock()}update()}
$('start').onclick=async()=>{clearInterval(alarmLoop);alarmLoop=null;if(state.awaiting){if(audio){await audio.close();audio=null;}if(state.phase==='clean'){state.round++;state.phase=breakFor(state.round)}else state.phase='clean';state.awaiting=false;state.remaining=cfg[state.phase]*60000;state.end=Date.now()+state.remaining;state.running=true;await unlock()}else{await unlock();if(state.running){state.remaining=Math.max(0,state.end-Date.now());state.running=false}else{state.end=Date.now()+state.remaining;state.running=true}}persist();wakeLock();update()};
function reset(){silence();state={phase:'clean',round:0,remaining:cfg.clean*60000,running:false,end:0};persist();wakeLock();render()}
$('stop').onclick=reset;$('lang').onclick=()=>{lang=lang==='de'?'en':'de';persist();render()};
$('settings').onclick=()=>{$('fields').innerHTML=['clean','short','medium','long','every','superEvery'].map(k=>`<label><span>${t(k)}${['clean','short','medium','long'].includes(k)?' ('+t('minute')+')':''}</span><input type="number" id="cfg-${k}" min="1" max="${k.includes('very')?99:240}" step="1" required value="${cfg[k]}"></label>`).join('');$('sound').value=cfg.sound;$('volume').value=cfg.volume;$('dialog').showModal()};$('close').onclick=()=>$('dialog').close();$('test').onclick=async()=>{await unlock();play($('sound').value,Number($('volume').value))};$('form').onsubmit=e=>{e.preventDefault();for(const k of ['clean','short','medium','long','every','superEvery'])cfg[k]=Number($('cfg-'+k).value);cfg.sound=$('sound').value;cfg.volume=Number($('volume').value);cfg.auto=false;$('dialog').close();reset()};
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else $('installDialog').showModal()};$('installClose').onclick=()=>$('installDialog').close();document.addEventListener('visibilitychange',()=>{if(!document.hidden){tick();wakeLock()}});window.addEventListener('pagehide',persist);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});render();tick();setInterval(tick,250);
